#include <iostream>
#include <algorithm>

int main() {
    int val1, val2;
    std::cin >> val1 >> val2;
    int small = std::min(val1, val2);
    int large = std::max(val1, val2);
    if (small == 1) {
        std::cout << ((large / 6 * 3 + std::max(large % 6 - 3, 0)) << 1) << std::endl;
    } else if (small == 2) {
        if (large == 2) {
            std::cout << 0 << std::endl;
        } else if (large == 3) {
            std::cout << 4 << std::endl;
        } else if (large == 7) {
            std::cout << 12 << std::endl;
        } else {
            std::cout << (large << 1) << std::endl;
        }
    } else {
        std::cout << (1LL * small * large / 2 * 2) << std::endl;
    }
    return 0;
}
